<?php require __DIR__.'/inc/page_helpers.php';$id=(int)($_GET['id']??($currentUser['id']??0));$q=$db->prepare('SELECT id,username,blurb,created_at,last_seen FROM users WHERE id=? AND account_status=\'active\'');$q->execute([$id]);$profile=$q->fetch();$owned=[];if($profile){$q=$db->prepare('SELECT c.id,c.name,c.type FROM inventory i JOIN catalog_items c ON c.id=i.item_id WHERE i.user_id=?');$q->execute([$id]);$owned=$q->fetchAll();}page_start($profile?$profile['username']:'User not found');?><section class="Panel"><?php if(!$profile):?><h1>User not found</h1><?php else:?><h1><?=e($profile['username'])?></h1><p><?=nl2br(e($profile['blurb']))?></p><p>Joined <?=e($profile['created_at'])?></p><h2>Inventory</h2><?php foreach($owned as $i):?><p><a href="/Item.php?id=<?=(int)$i['id']?>"><?=e($i['name'])?></a> (<?=e($i['type'])?>)</p><?php endforeach;?><?php if(!$owned):?><p>No items yet.</p><?php endif;?><?php if($currentUser&&(int)$currentUser['id']!==$id):?><p><a href="/My/PrivateMessage.php?to=<?=e($profile['username'])?>">Send private message</a></p><form method="post" action="/Report.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="user"><input type="hidden" name="id" value="<?=(int)$profile['id']?>"><label>Report reason<input name="reason" maxlength="1000" required></label><button>Report user</button></form><?php endif;?><?php endif;?></section><?php page_end();?>